const savedQuoteData=localStorage.getItem(QUOTE_KEY);
if(savedQuoteData)quoteData=JSON.parse(savedQuoteData);
else localStorage.setItem(QUOTE_KEY,JSON.stringify(quoteData));
if(!quoteData.titles)quoteData.titles=[];
if(!Array.isArray(quoteData.categories))quoteData.categories=['水電','木作','泥作','油漆','其他'];
quoteData.items.forEach((it,i)=>{
  if(it.sortOrder==null)it.sortOrder=i+1;
  const c=it.category||'其他';
  if(!quoteData.categories.includes(c))quoteData.categories.push(c);
});
function qcategories(){
  if(!Array.isArray(quoteData.categories))quoteData.categories=['水電','木作','泥作','油漆','其他'];
  return quoteData.categories.filter((x,i,a)=>x&&a.indexOf(x)===i);
}
// === 報價廠商獨立於各工種 ===
// 每個工種各自管理自己的廠商名稱與報價，不會互相連動。
function ensureVendorScopes(){
  if(!quoteData || !Array.isArray(quoteData.vendors)) quoteData.vendors=[];
  const cats=qcategories();
  if(quoteData.vendorScopeVersion===2 && quoteData.vendors.every(v=>v.type!=='廠商' || v.category)) return;
  const old=quoteData.vendors.filter(v=>v.type==='廠商' && !v.category);
  const existing=quoteData.vendors.filter(v=>v.type==='廠商' && v.category);
  const general=quoteData.vendors.filter(v=>v.type==='基準');
  const newVendors=[];
  const map={};
  cats.forEach(cat=>{
    const scoped=existing.filter(v=>v.category===cat);
    if(scoped.length){ scoped.forEach(v=>newVendors.push(v)); return; }
    old.forEach(v=>{
      const id='v_'+cat+'_'+v.id;
      newVendors.push({id,name:v.name,type:'廠商',category:cat});
      map[cat+'|'+v.id]=id;
    });
  });
  // 若原本只有全域廠商，將既有各工種項目的報價轉移到各自工種的新廠商ID。
  quoteData.items.forEach(it=>{
    const cat=it.category||'其他';
    const src=(it.vendors && typeof it.vendors==='object')?it.vendors:{};
    const out={};
    old.forEach(v=>{
      const nid=map[cat+'|'+v.id];
      if(nid) out[nid]=src[v.id] ?? null;
    });
    Object.keys(src).forEach(k=>{
      if(!old.some(v=>v.id===k)) out[k]=src[k];
    });
    it.vendors=out;
  });
  quoteData.vendors=[...general,...newVendors];
  quoteData.vendorScopeVersion=2;
  qsave();
}
ensureVendorScopes();
function qcategoryOptions(selected){
  return qcategories().map(c=>`<option value="${esc(c)}" ${c===selected?'selected':''}>${esc(c)}</option>`).join('');
}
