function quoteHome(){
  main.innerHTML = `
    <button class="back" onclick="home()">← 返回工程管理</button>
    <div class="section"><div><b>報價管理</b><div class="muted">每個工種的廠商獨立管理，修改木作不會影響水電。</div></div></div>
    <div class="section"><div><b>工種報價</b><div class="muted">進入工種後，廠商名稱只會套用在該工種。</div></div><button class="light" onclick="newQuoteCategory()">＋ 新增工種</button></div>
    ${qcategories().map(c=>`<div class="card" onclick="quoteCategory('${esc(c).replace(/'/g,"\\'")}')" style="cursor:pointer;display:flex;justify-content:space-between;align-items:center">
      <div><h3 style="margin:0 0 5px">${esc(c)}</h3><div class="muted">${quoteData.items.filter(x=>(x.category||'其他')===c).length} 個細項　｜　${quoteData.vendors.filter(v=>v.type==='廠商'&&v.category===c).length} 家廠商</div></div><b style="font-size:22px">→</b></div>`).join('')}
    <div class="hint">例如：水電可以是「○○水電、△△水電」；木作可以另外設定「□□木工、△△木作」，彼此完全獨立。</div>`;
}
function quoteCategory(category){
  const items=quoteData.items.filter(x=>(x.category||'其他')===category);
  main.innerHTML=`<button class="back" onclick="quoteHome()">← 報價管理</button>
    <div class="section"><div><b>${esc(category)}</b><div class="muted">報價細項比較表</div></div><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="light" onclick="newVendor('${category}')">＋ 新增廠商</button><button class="light" onclick="newQuoteTitle('${category}')">＋ 新增項目標題</button><button onclick="newQuoteItem('${category}')">＋ 新增細項</button></div></div>
    <div class="card"><div class="muted">每一列是一個細項；廠商名稱可直接修改，項目可用 ↑ ↓ 調整順序。</div></div>
    ${items.length?quoteTable(category):`<div class="empty">這個工種還沒有報價細項。<br><br><button onclick="newQuoteItem('${category}')">＋ 新增第一個細項</button></div>`}`;
}
function quoteTable(category){
  const allItems=quoteData.items.filter(x=>(x.category||'其他')===category);
  const items=[...allItems].sort((a,b)=>(a.sortOrder??0)-(b.sortOrder??0));
  const titles=(quoteData.titles||[]).filter(x=>(x.category||'其他')===category);
  const vendors=quoteData.vendors.filter(v=>v.type==='廠商' && v.category===category);
  const row=it=>{
    const diffs=[];
    const cells=vendors.map(v=>{const p=it.vendors?.[v.id] ?? it.prices?.[v.id];const d=typeof p==='number'&&it.benchmark?Math.round((p-it.benchmark)/it.benchmark*100):null;if(d!==null)diffs.push(d);return `<td style="padding:12px;border-bottom:1px solid #eee;text-align:right;white-space:nowrap"><b>${p==null?'—':p.toLocaleString()}</b>${d!==null?`<div class="muted small">${d>0?'+':''}${d}%</div>`:''}</td>`}).join('');
    const avg=diffs.length?Math.round(diffs.reduce((a,b)=>a+b,0)/diffs.length):null;
    const pos=items.findIndex(x=>String(x.id)===String(it.id));
    return `<tr><td style="padding:12px;border-bottom:1px solid #eee"><b>${esc(it.name)}</b></td><td style="padding:12px;border-bottom:1px solid #eee">${esc(it.spec||'')}</td><td style="padding:12px;border-bottom:1px solid #eee;text-align:right">${it.qty??''}</td><td style="padding:12px;border-bottom:1px solid #eee;text-align:center">${esc(it.unit||'')}</td><td style="padding:12px;border-bottom:1px solid #eee;text-align:right">${Number(it.benchmark||0).toLocaleString()}</td>${cells}<td style="padding:12px;border-bottom:1px solid #eee;text-align:center">${avg===null?'—':avg>5?'偏高':avg<-5?'偏低':'接近'}</td><td style="padding:12px;border-bottom:1px solid #eee;white-space:nowrap"><button class="orderbtn" onclick="moveQuoteItem(${it.id},-1)" ${pos===0?'disabled':''}>↑</button> <button class="orderbtn" onclick="moveQuoteItem(${it.id},1)" ${pos===items.length-1?'disabled':''}>↓</button> <button class="light" onclick="editQuoteItem(${it.id})">編輯</button></td></tr>`;
  };
  const titleRow=t=>`<tr><td colspan="${7+vendors.length}" style="padding:13px 12px;background:#f3f3f3;border-bottom:1px solid #ddd;font-weight:700">${esc(t.name)} <button class="light" style="float:right;padding:5px 9px" onclick="editQuoteTitle(${t.id})">編輯標題</button></td></tr>`;
  let body='';
  titles.forEach(t=>{body+=titleRow(t);items.filter(it=>it.titleId===t.id).forEach(it=>body+=row(it));});
  items.filter(it=>!it.titleId || !titles.some(t=>t.id===it.titleId)).forEach(it=>body+=row(it));
  return `<div class="card" style="overflow-x:auto;padding:0"><table style="width:100%;min-width:820px;border-collapse:collapse;font-size:13px"><thead><tr><th style="text-align:left;padding:12px;border-bottom:1px solid #ddd">品名</th><th style="padding:12px;border-bottom:1px solid #ddd">規格</th><th style="padding:12px;border-bottom:1px solid #ddd">數量</th><th style="padding:12px;border-bottom:1px solid #ddd">單位</th><th style="padding:12px;border-bottom:1px solid #ddd">一般行情</th>${vendors.map(v=>`<th style="padding:12px;border-bottom:1px solid #ddd;cursor:pointer" onclick="editVendorName('${v.id}','${esc(category).replace(/'/g,"\\'")}')" title="點擊修改廠商名稱">${esc(v.name)}<div class="muted small">點擊修改</div></th>`).join('')}<th style="padding:12px;border-bottom:1px solid #ddd">判斷</th><th style="padding:12px;border-bottom:1px solid #ddd"></th></tr></thead><tbody>${body}</tbody></table></div>`;
}
function moveQuoteItem(id,dir){
  const category=quoteData.items.find(x=>String(x.id)===String(id))?.category||'其他';
  const arr=quoteData.items.filter(x=>(x.category||'其他')===category).sort((a,b)=>(a.sortOrder??0)-(b.sortOrder??0));
  const i=arr.findIndex(x=>String(x.id)===String(id)), n=i+dir;
  if(i<0||n<0||n>=arr.length)return;
  [arr[i].sortOrder,arr[n].sortOrder]=[arr[n].sortOrder,arr[i].sortOrder];
  arr.forEach((x,k)=>x.sortOrder=k+1);
  qsave(); quoteCategory(category);
}
function newVendor(category){
  category=category||'其他';
  openModal(`
    <h3>新增「${esc(category)}」廠商</h3>
    <input id="newVendorName" type="text" autocomplete="off" placeholder="請輸入廠商名稱">
    <div class="hint">這家廠商只會出現在「${esc(category)}」，不會影響其他工種。</div>
    <div class="modal-actions">
      <button onclick="closeModal()">取消</button>
      <button class="primary" onclick="saveNewVendor('${esc(category)}')">新增</button>
    </div>
  `);
  setTimeout(()=>{
    const el=document.getElementById('newVendorName');
    if(el){el.focus();el.addEventListener('keydown',e=>{if(e.key==='Enter')saveNewVendor(category);});}
  },50);
}
function saveNewVendor(category){
  const el=document.getElementById('newVendorName');
  const name=(el?.value||'').trim();
  if(!name){alert('請輸入廠商名稱');return;}
  const vendors=quoteData.vendors.filter(v=>v.type==='廠商'&&v.category===category);
  if(vendors.some(v=>(v.name||'').trim()===name)){alert('這個工種已有同名廠商');return;}
  const id='v_'+Date.now()+'_'+Math.random().toString(36).slice(2,7);
  quoteData.vendors.push({id,name,type:'廠商',category});
  quoteData.items.filter(it=>(it.category||'其他')===category).forEach(it=>{
    if(!it.vendors||typeof it.vendors!=='object')it.vendors={};
    it.vendors[id]=null;
  });
  qsave();closeModal();quoteCategory(category);
}
function editVendorName(id,category){
  const v=quoteData.vendors.find(x=>x.id===id && x.type==='廠商');
  category=v?.category||category||'其他';
  if(!v)return;
  openModal(`<h2>修改「${esc(category)}」廠商名稱</h2><label>廠商名稱</label><input id="vendorNameEdit" value="${esc(v.name)}" placeholder="例如：○○水電"><div class="hint">只修改「${esc(category)}」的廠商名稱，其他工種不會改變。</div><div class="actions"><button class="light" onclick="closeModal()">取消</button><button onclick="saveVendorName('${id}','${esc(category)}')">儲存</button></div>`);
}
function saveVendorName(id,category){
  const v=quoteData.vendors.find(x=>x.id===id&&x.type==='廠商'),el=document.getElementById('vendorNameEdit');
  if(!v||!el)return;
  const name=el.value.trim();
  if(!name){alert('請填寫廠商名稱');return;}
  v.name=name;qsave();closeModal();quoteCategory(v.category||category||'其他');
}
function newQuoteTitle(category){editQuoteTitle(null,category)}
function editQuoteTitle(id,category){
  const t=id?(quoteData.titles||[]).find(x=>x.id===id):null; category=t?.category||category||'其他';
  openModal(`<h2>${t?'編輯項目標題':'新增項目標題'}</h2><label>工種</label><select id="qtcat">${qcategoryOptions(category)}</select><label>項目標題</label><input id="qtn" value="${esc(t?.name||'')}" placeholder="例如：插座項目"><div class="actions"><button class="light" onclick="closeModal()">取消</button><button onclick="saveQuoteTitle(${id||0})">儲存</button></div>`);
  document.getElementById('qtcat').value=category;
}
function saveQuoteTitle(id){
  const name=document.getElementById('qtn').value.trim(); if(!name){alert('請填寫項目標題');return;}
  if(!quoteData.titles)quoteData.titles=[];
quoteData.items.forEach((it,i)=>{if(it.sortOrder==null)it.sortOrder=i+1;});
  const obj={id:id||Date.now(),category:document.getElementById('qtcat').value,name};
  if(id){const k=quoteData.titles.findIndex(x=>x.id===id);if(k>=0)quoteData.titles[k]=obj;else quoteData.titles.push(obj)}else quoteData.titles.push(obj);
  qsave();closeModal();quoteCategory(obj.category);
}
function newQuoteItem(category){editQuoteItem(null,category||'其他')}
function editQuoteItem(id,category){
  const it=id?quoteData.items.find(x=>x.id===id):null; category=it?.category||category||'其他';
  const vendorInputs=quoteData.vendors.filter(v=>v.type==='廠商'&&v.category===category).map(v=>`<label>${esc(v.name)} 報價</label><input id="qp_${v.id}" type="number" value="${it?.vendors?.[v.id] ?? it?.prices?.[v.id] ?? ''}" placeholder="例如 450">`).join('');
  openModal(`<h2>${it?'編輯報價細項':'新增報價細項'}</h2><label>工種</label><select id="qcat">${qcategoryOptions(category)}</select><label>項目標題</label><select id="qtitle"><option value="">未分類</option>${(quoteData.titles||[]).filter(t=>(t.category||'其他')===category).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><label>品名</label><input id="qn" value="${esc(it?.name||'')}" placeholder="例如：插座"><label>規格／說明</label><input id="qspe" value="${esc(it?.spec||it?.note||'')}" placeholder="例如：Panasonic G系列・含安裝"><label>單位</label><input id="qu" value="${esc(it?.unit||'個')}"><label>數量</label><input id="qq" type="number" value="${it?.qty??1}"><label>一般行情／基準單價</label><input id="qb" type="number" value="${it?.benchmark??''}">${vendorInputs}<label>備註</label><textarea id="qnote">${esc(it?.note||'')}</textarea><div class="actions"><button class="light" onclick="closeModal()">取消</button><button onclick="saveQuoteItem(${id||0})">儲存</button></div>`);
  document.getElementById('qcat').value=category; if(document.getElementById('qtitle'))document.getElementById('qtitle').value=it?.titleId||'';
}
function saveQuoteItem(id){
  const name=document.getElementById('qn').value.trim(), benchmark=document.getElementById('qb').value;
  if(!name||benchmark===''){alert('請填寫品名與一般行情');return;}
  const selectedCategory=document.getElementById('qcat').value||'其他'; const vendors={}; quoteData.vendors.filter(v=>v.type==='廠商'&&v.category===selectedCategory).forEach(v=>{const el=document.getElementById('qp_'+v.id);vendors[v.id]=el&&el.value!==''?Number(el.value):null});
  const obj={id:id||Date.now(),category:document.getElementById('qcat').value,titleId:document.getElementById('qtitle')?.value?Number(document.getElementById('qtitle').value):null,name,spec:document.getElementById('qspe').value,unit:document.getElementById('qu').value||'式',qty:Number(document.getElementById('qq').value||1),benchmark:Number(benchmark),vendors,note:document.getElementById('qnote').value};
  if(id){const k=quoteData.items.findIndex(x=>x.id===id);if(k>=0)quoteData.items[k]=obj;else quoteData.items.push(obj)}else quoteData.items.push(obj);
  qsave();closeModal();quoteCategory(obj.category);
}

