function recoverPhotos(){
  let changed=false;
  if(!Array.isArray(data.trades)) data.trades=[];
  RECOVERY_PHOTOS.forEach(src=>{
    const target=data.trades.find(t=>t && t.name===src.name);
    if(!target)return;
    if(!Array.isArray(target.photos)) target.photos=[];
    const existing=new Set(target.photos.map(p=>p && p.id));
    src.photos.forEach(p=>{
      if(p && p.id && !existing.has(p.id)){ target.photos.push(p); changed=true; }
    });
  });
  if(changed){
    localStorage.setItem(KEY,JSON.stringify(data));
    window.__photosRecovered=true;
  }
}
function save(){localStorage.setItem(KEY,JSON.stringify(data))}


// === 外部資料檔連接 ===
// project-data.json 是「資料種子」：有資料時載入並合併；瀏覽器中的既有資料優先保留。
async function loadProjectDataFile(){
  try{
    const res=await fetch('data/project-data.json',{cache:'no-store'});
    if(!res.ok)throw new Error('HTTP '+res.status);
    const external=await res.json();
    if(!external || typeof external!=='object')return data;

    // 外部 JSON 是「種子資料」，瀏覽器已存在的使用者資料優先。
    // 只有目前沒有資料時才使用 JSON 的預設工程。
    const hasUserTrades=Array.isArray(data.trades) && data.trades.length>0;
    const hasUserProjects=Array.isArray(data.projects) && data.projects.length>0;
    const hasUserGroups=Array.isArray(data.scheduleGroups) && data.scheduleGroups.length>0;

    if(!hasUserGroups && Array.isArray(external.categories)){
      data.scheduleGroups=external.categories.map((c,i)=>({
        name:String(c.name||'').trim(),
        order:Number(c.order)||i+1,
        showNumber:c.showNumber===true
      })).filter(c=>c.name);
    }
    if(!hasUserTrades && Array.isArray(external.items) && external.items.length){
      data.trades=external.items;
    }
    if(!hasUserProjects && Array.isArray(external.projects) && external.projects.length){
      data.projects=external.projects;
    }
  }catch(err){
    // file:// 開啟時瀏覽器可能禁止 fetch 本機 JSON；此時繼續使用 localStorage/default data。
    console.info('project-data.json 未載入，沿用瀏覽器現有資料。',err.message);
  }
  return data;
}
